protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    // HasIndex throws on Cosmos in EF Core 9; manage indexing via Azure portal/Bicep.
    // Preserve "Discriminator" property name for existing documents (EF9 defaults to "$type").
    modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");
    // Preserve "Blog|1" compound id format for existing documents (EF9 defaults to key-only).
    modelBuilder.Entity<Blog>().HasRootDiscriminatorInJsonId(true);
}

